use std::{collections::HashMap,fs,path::{Path,PathBuf},process::{Command,Stdio},sync::Arc,io::Write};
use revia_lib::{git::{CommandLog,status::ChangesKind},recovery::{RecoveryStore,RestoreExpectation,RestorePhase},session::{WorktreeSession,ChangeEntry},shell::{ShellEnv,EnvCaptureInfo}};
struct Fixture {repo:PathBuf, vars:HashMap<String,String>, paths:Vec<String>, store:RecoveryStore}
impl Fixture {
 fn new(root:&Path,name:&str)->Self {
  let base=root.join(name); let repo=base.join("repo"); let home=base.join("home"); fs::create_dir_all(&repo).unwrap();fs::create_dir_all(&home).unwrap();
  let path=std::env::var("PATH").unwrap(); let paths=std::env::split_paths(&path).map(|p|p.display().to_string()).collect();
  let vars=HashMap::from([("PATH".into(),path),("HOME".into(),home.display().to_string()),("GIT_CONFIG_GLOBAL".into(),"/dev/null".into()),("GIT_CONFIG_NOSYSTEM".into(),"1".into()),("GIT_TERMINAL_PROMPT".into(),"0".into())]);
  let f=Self{repo,vars,paths,store:RecoveryStore::new(base.join("data"))}; f.git(&["init","-q"]);f.git(&["config","user.name","Fixture"]);f.git(&["config","user.email","fixture@example.invalid"]);f.git(&["config","commit.gpgsign","false"]);f.git(&["config","core.autocrlf","false"]);f
 }
 fn command(&self,args:&[&str])->Command {let mut c=Command::new("git");c.current_dir(&self.repo).env_clear().envs(&self.vars).args(args);c}
 fn git(&self,args:&[&str])->String {let o=self.command(args).output().unwrap();assert!(o.status.success(),"{:?} {}",args,String::from_utf8_lossy(&o.stderr));String::from_utf8_lossy(&o.stdout).into_owned()}
 fn git_input(&self,args:&[&str],input:&str){let mut c=self.command(args).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();c.stdin.take().unwrap().write_all(input.as_bytes()).unwrap();let o=c.wait_with_output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));}
 fn setup(&self){fs::write(self.repo.join("target.txt"),b"base\n").unwrap();self.git(&["add","--all"]);self.git(&["commit","-qm","base"]);fs::write(self.repo.join("target.txt"),b"saved change\n").unwrap();}
 fn session(&self)->Arc<WorktreeSession>{WorktreeSession::open("fixture",&self.repo,ShellEnv{vars:self.vars.clone(),path:self.paths.clone(),info:EnvCaptureInfo{worktree:self.repo.display().to_string(),shell:"fixture".into(),elapsed_ms:0,timed_out:false,used_fallback:true,var_count:self.vars.len(),path_entries:self.paths.clone(),diagnostics:None}},Arc::new(CommandLog::default())).unwrap()}
 fn entry(&self,s:&WorktreeSession)->ChangeEntry{s.refresh().unwrap().entries.into_iter().find(|e|e.path=="target.txt"&&e.changes==ChangesKind::Unstaged).unwrap()}
}

fn prepared(root: &Path,name:&str)->(Fixture,Arc<WorktreeSession>,String,RestoreExpectation){let f=Fixture::new(root,name);f.setup();let s=f.session();let e=f.entry(&s);s.discard_file(&e.path,&e.fingerprint,&e.snapshot_revision,&f.store).unwrap();let id=f.store.list(None).unwrap()[0].id.clone();let i=s.inspect_record(&id,&f.store).unwrap();let exp=RestoreExpectation{paths:i.paths,state:i.state};(f,s,id,exp)}
fn unmerge(f:&Fixture){let oid=f.git(&["rev-parse","HEAD:target.txt"]);let oid=oid.trim();f.git_input(&["update-index","--index-info"],&format!("0 {}\ttarget.txt\n100644 {oid} 1\ttarget.txt\n100644 {oid} 2\ttarget.txt\n100644 {oid} 3\ttarget.txt\n","0".repeat(40)));}
fn main(){let root=PathBuf::from(std::env::args().nth(1).unwrap());
 let(f,s,id,exp)=prepared(&root,"late-edit");let r=s.restore_record_with_hook(&id,&exp,&f.store,|p|{if matches!(p,RestorePhase::BeforeWrite){fs::write(f.repo.join("target.txt"),b"later external edit\n")?;}Ok(())});println!("late_edit_restore_ok={}",r.is_ok());println!("late_edit_overwritten={}",fs::read(f.repo.join("target.txt")).unwrap()==b"saved change\n");
 let(f,s,id,exp)=prepared(&root,"initial-unmerged");unmerge(&f);let r=s.restore_record(&id,&exp,&f.store);println!("initial_unmerged_restore_error={:?}",r.unwrap_err().kind);println!("initial_unmerged_target_preserved={}",fs::read(f.repo.join("target.txt")).unwrap()==b"base\n");
 let(f,s,id,exp)=prepared(&root,"late-unmerged");let r=s.restore_record_with_hook(&id,&exp,&f.store,|p|{if matches!(p,RestorePhase::BeforeWrite){unmerge(&f);}Ok(())});println!("late_unmerged_present={}",!f.git(&["ls-files","-u"]).is_empty());println!("late_unmerged_restore_ok={}",r.is_ok());println!("late_unmerged_worktree_written={}",fs::read(f.repo.join("target.txt")).unwrap()==b"saved change\n");
 let(f,s,id,exp)=prepared(&root,"completion-io");let record_dir=f.repo.parent().unwrap().join("data").join("recovery").join(&id);let r=s.restore_record_with_hook(&id,&exp,&f.store,|p|{if matches!(p,RestorePhase::BeforeComplete){fs::create_dir(record_dir.join("restore.next"))?;}Ok(())});println!("completion_io_error={:?}",r.unwrap_err().kind);println!("completion_target_already_written={}",fs::read(f.repo.join("target.txt")).unwrap()==b"saved change\n");println!("completion_disk_journal={:?}",f.store.restore_journal(&id).unwrap().unwrap().state);drop(s);let reopened_store=RecoveryStore::new(f.repo.parent().unwrap().join("data"));println!("reopened_list_status={:?}",reopened_store.list(None).unwrap()[0].status);fs::write(f.repo.join("target.txt"),b"base\n").unwrap();let s=f.session();let i=s.inspect_record(&id,&reopened_store).unwrap();println!("retry_inspection_state={:?}",i.state);let exp=RestoreExpectation{paths:i.paths,state:i.state};let r=s.restore_record(&id,&exp,&reopened_store);println!("retry_restore_error={:?}",r.unwrap_err());
}
